changeSet.sql:
UPDATE UNIPOST_TENANT_BILLING SET payment_provider = 'PAYOS', provider_customer_ref = payos_customer_id, current_order_ref = CASE WHEN current_order_code IS NOT NULL THEN current_order_code::text ELSE NULL END, currency = 'VND', billing_metadata = '{}'::jsonb WHERE payment_provider IS NULL OR payment_provider = 'PAYOS';
-- 3. Create index on generic order reference and provider lookup CREATE INDEX IF NOT EXISTS idx_tenant_billing_order_ref ON UNIPOST_TENANT_BILLING (payment_provider, current_order_ref);
CREATE INDEX IF NOT EXISTS idx_tenant_billing_customer_ref ON UNIPOST_TENANT_BILLING (payment_provider, provider_customer_ref);
